import { createHash } from 'node:crypto';
import { mkdir, rename, rm, stat } from 'node:fs/promises';
import { extname, join } from 'node:path';
import { isPreparableExtension, planPlaybackPreparation } from '../../domain/playback-preparation';
import type { MediaInspector } from '../../domain/playability';
import type { MediaRemuxer } from '../../domain/ports';

/** A file the desktop media protocol can serve (original or prepared copy). */
export interface PreparedPlayback {
  path: string;
  /** True when `path` is a cached MP4 generated by the core. */
  prepared: boolean;
}

/** Prepares a library video for the desktop player. */
export interface MediaPlaybackService {
  prepare(absolutePath: string): Promise<PreparedPlayback>;
}

export interface PrepareMediaPlaybackDependencies {
  inspector: MediaInspector;
  remuxer: MediaRemuxer;
  /** Where prepared MP4 copies live (never inside the user's library). */
  cacheDir: string;
}

async function existingFile(path: string): Promise<boolean> {
  try {
    const stats = await stat(path);
    return stats.isFile() && stats.size > 0;
  } catch {
    return false;
  }
}

function cacheKey(absolutePath: string, size: number, modifiedMs: number): string {
  return createHash('sha1').update(`${absolutePath}\0${size}\0${modifiedMs}`).digest('hex');
}

/**
 * Decides how a video should reach Chromium and, when its container is not
 * native (e.g. MPEG-TS), remuxes it once into an MP4 cache. The source file is
 * never modified; repeated range requests reuse the cached copy.
 */
export class PrepareMediaPlayback implements MediaPlaybackService {
  private readonly inFlight = new Map<string, Promise<PreparedPlayback>>();

  constructor(private readonly deps: PrepareMediaPlaybackDependencies) {}

  async prepare(absolutePath: string): Promise<PreparedPlayback> {
    // Native containers and non-video files never touch ffprobe/ffmpeg.
    if (!isPreparableExtension(extname(absolutePath))) {
      return { path: absolutePath, prepared: false };
    }

    const stats = await stat(absolutePath);
    const destination = join(
      this.deps.cacheDir,
      `${cacheKey(absolutePath, stats.size, stats.mtimeMs)}.mp4`,
    );
    if (await existingFile(destination)) return { path: destination, prepared: true };

    const running = this.inFlight.get(destination);
    if (running) return running;

    const work = this.prepareOnce(absolutePath, destination);
    this.inFlight.set(destination, work);
    try {
      return await work;
    } finally {
      this.inFlight.delete(destination);
    }
  }

  private async prepareOnce(absolutePath: string, destination: string): Promise<PreparedPlayback> {
    let plan;
    try {
      plan = planPlaybackPreparation(await this.deps.inspector.inspect(absolutePath));
    } catch {
      return { path: absolutePath, prepared: false };
    }
    if (plan.mode !== 'remux') return { path: absolutePath, prepared: false };

    await mkdir(this.deps.cacheDir, { recursive: true });
    const temporary = `${destination}.${process.pid}.${Date.now()}.tmp`;
    try {
      await this.deps.remuxer.remux(absolutePath, temporary);
      await rename(temporary, destination);
      return { path: destination, prepared: true };
    } catch {
      await rm(temporary, { force: true }).catch(() => undefined);
      return { path: absolutePath, prepared: false };
    }
  }
}
